        if (typeof G.cutBoxes !== "function" || typeof G.cutParts !== "function") return;
        const W = 1366, H = 560;
        const planted = Object.assign([{ poly: [[0, 0], [100, 0], [100, 100], [0, 100]] }, { poly: [[50, 50], [150, 50], [150, 150], [50, 150]] }], { meta: { top: [], bot: [] } });
