                            host.style.setProperty(HOST[0], `${insets[0]}px`);
                            host.style.setProperty(HOST[1], `${insets[1]}px`);
                            body.style.setProperty(BODY[0], lift);
                            body.style.setProperty(BODY[1], clear);
