            seen.push(read());
            const first = room.remoteParticipants.get(b.id);
            room.emit("participantDisconnected", first);
            seen.push(read());
            room.remoteParticipants.delete(b.id);
            rig.leave(room, d.id);
            seen.push(read());
            V.openVoiceList(rig.watch);
            seen.push(alone());
            rig.leave(room, stranger.identity);
            seen.push(read(), alone());
