        const unlisted = [Boolean(inRow(P1, `.drpg-passage-chip[data-drpg-actor="${B.id}"]`)), Boolean(inRow(P1, `[data-drpg-actor="${B.id}"]`))];
        await stores.mastermind.patch(G.RECORD, { actorId: null });
