        const users = game.users.filter(user => user.id !== game.user.id && !user.isGM).slice(0, 3);
        const NAMES = ["A", "B", "C"], idOf = name => users[NAMES.indexOf(name)].id, nameOf = id => NAMES[users.findIndex(u => u.id === id)] ?? "?";
