        now = 0;
        speak(first, ["B"]);
        at(999);
        at(1000);
        now = 1500;
        speak(first, ["C", "B"]);
        at(1500);
        at(2500);
        exclude = "actor-C";
        at(2500, "objector C");
        exclude = null;
        now = 3000;
        speak(first, []);
        at(3000, "silence");
        now = 3100;
        speak(first, ["A"]);
        now = 3600;
        speak(first, []);
        at(3600, "cough");
