        at(5200, "new Room");
        now = 6500;
        speak(first, ["B"]);
        at(6500, "old Room");
        const listeners = [first.listenerCount("activeSpeakersChanged"), second.listenerCount("activeSpeakersChanged")];
        speak(second, ["B"]);
        at(7600, "new Room B");
        inTrial = false;
        at(7600, "ended");
        inTrial = true;
        at(7600, "again");
