        read.analyze = [...ana.querySelectorAll(".drpg-details-layer[data-drpg-when] li")].map(li => li.closest(".drpg-details-layer").dataset.drpgWhen).sort();
        const tam = tamperThresholdFacts(actor, cleanup);
