            read.first = PT.markTrayMore(root);
            PT.markTrayMore(root);
            read.watched = observers.filter(o => o.live).flatMap(o => o.targets.map(el => (el === list ? "list" : el === rows ? "rows" : "other")));
            heights(200, 120);
            fire();
