            const P = [v.x + ox, v.y + oy], cs = Math.cos(phi), sn = Math.sin(phi);
            const R = (x, y) => [P[0] + (x - P[0]) * cs - (y - P[1]) * sn, P[1] + (x - P[0]) * sn + (y - P[1]) * cs];
