        const who = { id: "r2025", name: "R2025 student", items: [item("R2025 wrench", "tool", 1), item("R2025 rope", "tool", 0), item("R2025 knife", "crimeTool", 2)] };
        const box = document.createElement("div");
        box.innerHTML = G.holdingsHtml(who);
