                shapes: rect ? [{ type: "rectangle", x: rect[0], y: rect[1], width: rect[2], height: rect[3] }] : [],
                ...(polygons ? { polygons: polygons.map(points => ({ points })) } : {}),
                ...(tree ? { polygonTree: tree } : {})
